code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(g[r + dr][c + dc] == 3
                                     for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                                     if (dr, dc) != (0, 0)):
                centers.append((r, c))
    if not centers:
        return g
    vertical = []
    horizontal = []
    for r, c in centers:
        row_count = sum(v == 2 for v in g[r])
        col_count = sum(g[i][c] == 2 for i in range(h))
        vertical.append(col_count > row_count)
        horizontal.append(row_count > col_count)
    vertical_stripes = any(vertical)
    if vertical_stripes:
        stripe_positions = [c for c in range(w) if sum(g[r][c] == 2 for r in range(h)) >= 0.6 * h]
        for r, c in centers:
            for x in range(w):
                if g[r][x] == 0:
                    g[r][x] = 1
            for x in stripe_positions:
                if any((r, c) == (r, x) for r, c in centers):
                    continue
                for dr in (-1, 0, 1):
                    rr = r + dr
                    if 0 <= rr < h:
                        for dc in (-1, 0, 1):
                            cc = x + dc
                            if 0 <= cc < w and (dr != 0 or dc != 0):
                                g[rr][cc] = 1
    else:
        stripe_positions = [r for r in range(h) if sum(v == 2 for v in g[r]) >= 0.6 * w]
        for r, c in centers:
            for y in range(h):
                if g[y][c] == 0:
                    g[y][c] = 1
            for y in stripe_positions:
                if any((r, c) == (y, c) for r, c in centers):
                    continue
                for dr in (-1, 0, 1):
                    rr = y + dr
                    if 0 <= rr < h:
                        for dc in (-1, 0, 1):
                            cc = c + dc
                            if 0 <= cc < w and (dr != 0 or dc != 0):
                                g[rr][cc] = 1
    return g
'''
